def count_passing_ways(n: int, m: int) -> int:
    if n == 0 or m == 0:
        return 0

    # Initialize a 2D list to store the number of ways to pass the ball
    dp = [[0 for _ in range(m + 1)] for _ in range(n)]

    # Base case: There is one way to pass the ball 0 times (doing nothing)
    for i in range(n):
        dp[i][0] = 1

    # Fill the dp table
    for i in range(n):
        for j in range(1, m + 1):
            dp[i][j] = dp[(i - 1) % n][j - 1] + dp[(i + 1) % n][j - 1]

    # The result is the number of ways to pass the ball m times starting from any student
    return dp[0][m]
```

