def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Initialize the left and right arrays
    left = [1] * n
    right = [1] * n

    # Fill the left array
    for i in range(1, n):
        if heights[i] > heights[i - 1]:
            left[i] = left[i - 1] + 1

    # Fill the right array
    for i in range(n - 2, -1, -1):
        if heights[i] > heights[i + 1]:
            right[i] = right[i + 1] + 1

    # Find the maximum length of the choir formation
    max_choir_length = 0
    for i in range(n):
        max_choir_length = max(max_choir_length, left[i] + right[i] - 1)

    # The minimum number of students to leave
    return n - max_choir_length
```
